mapper.select:
SELECT 
FROM routing r
LEFT JOIN material m ON m.id = r.product_id
WHERE r.deleted = false

    AND m.code = #{productCode}


    AND r.routing_version = #{version}


    AND r.status = #{status}



        ORDER BY ${sortColumn}

            ASC
            DESC



        ORDER BY r.effective_date DESC


, r.id ASC

mapper.update:
UPDATE routing
SET nodes = #{nodes,typeHandler=com.hengce.aps.infrastructure.persistence.handler.JsonbTypeHandler},
    edges = #{edges,typeHandler=com.hengce.aps.infrastructure.persistence.handler.JsonbTypeHandler},
    version = version + 1,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = false

mapper.select:
SELECT COUNT(1)
FROM routing
WHERE product_id = #{productId}
  AND routing_version = #{routingVersion}
  AND deleted = false

    AND id <> #{excludeId}

SELECT COUNT(1)
FROM routing
WHERE product_id = #{productId}
  AND status = 'ACTIVE'
  AND deleted = false

    AND id <> #{excludeId}
